import json, sys

results = []
with open('/root/schema_semantic_constrained_ie/outputs/test_cf_fallback_dryrun.jsonl') as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            results.append(json.loads(line))
        except json.JSONDecodeError as e:
            print(f"Line {i}: JSON error: {e}, first 100 chars: {line[:100]}")

cf_violations = 0
total_relations = 0

for r in results:
    parsed = r.get('parsed_output', {})
    if parsed is None:
        continue
    entities = parsed.get('entities', [])
    relations = parsed.get('relations', [])

    etype_map = {}
    for e in entities:
        if 'text' in e and 'type' in e:
            etype_map[e['text']] = e['type']

    total_relations += len(relations)
    for rel in relations:
        head = rel.get('head', '')
        tail = rel.get('tail', '')
        ht = rel.get('head_type', '')
        tt = rel.get('tail_type', '')

        if head in etype_map and ht != etype_map[head]:
            cf_violations += 1
            print(f"CF head: doc={r['doc_id']}, entity=\"{head}\", registry={etype_map[head]}, rel_head_type={ht}")
        if tail in etype_map and tt != etype_map[tail]:
            cf_violations += 1
            print(f"CF tail: doc={r['doc_id']}, entity=\"{tail}\", registry={etype_map[tail]}, rel_tail_type={tt}")

print(f"\nTotal samples: {len(results)}, Total relations: {total_relations}, CF violations: {cf_violations}")
